"""Freeze stack/VDP evidence before removing only verified generated files."""
import json
from run_core import ROOT
from archive_lossless_evidence import freeze,sha


def main():
 r=json.loads((ROOT/'analysis/stack_release_v0285_report.json').read_bytes());assert r['passed'] and not r['full_game_validated'] and r['md_sha256']==sha((ROOT/'gaw-megadrive.bin').read_bytes())
 prefix=json.loads((ROOT/'analysis/stack_release_v0285_worklog_prefix.json').read_bytes());assert sha((ROOT/'analysis/world_next.md').read_bytes()[:prefix['bytes']])==prefix['sha256']
 protected=[ROOT/'input/original.sms',ROOT/'gaw-megadrive.bin',ROOT/'gaw-title-megadrive.bin',*sorted((ROOT/'versions').glob('*/*.bin'))]
 before={p.relative_to(ROOT).as_posix():sha(p.read_bytes()) for p in protected};assert len(protected)==288
 roots=[];validation=ROOT/'validation'
 for pattern in ['stack-*','boss-lookahead-*','natural-v0280-bridge*-driver','dialogue-vblank-v028[45]','sprite-mask-production-v028[34]','dialogue-controls-*','dialogue-preparation-*','title-cadence*','menu-transition-*','audio-stream-equivalence']:
  roots += [p for p in validation.glob(pattern) if p.is_dir()]
 for family in ['natural-dungeon-route','natural-dungeon-combat','natural-service-route']:
  for pattern in ['*v028[1-5]*','*v0280-d2-bridge*','*v0280-d2-lookahead*','*v0280-d2-boss-entry-cut01']:
   roots += [p for p in (validation/family).glob(pattern) if p.is_dir()]
 roots=sorted(set(roots));paths=[p for folder in roots for p in folder.rglob('*') if p.is_file()]
 paths += [ROOT/n for n in r['evidence'] if (ROOT/n).exists()]
 paths += [p for p in validation.glob('*.log') if any(t in p.name for t in ['v028','stack-observer'])]
 paths += [ROOT/'megadrive/out/release'/n for n in ['rom.bin','rom.out','symbol.txt']]
 paths += [ROOT/'megadrive/src'/n for n in ['main.c','sound.inc','source_audio_reader.c','source_audio_reader.h','source_audio_fast.c','source_audio_fast.h']]
 paths += [ROOT/'tools'/n for n in ['build_stack_observer.py','profile_playable_stack.py','natural_dungeon_combat.py','natural_boss_lookahead.py','rebase_natural_campaign.py','replay_natural_campaign.py','validate_audio_stream_equivalence.py','summarize_stack_release_v0285.py','archive_stack_release_v0285.py','run_core.py']]
 paths += [ROOT/n for n in ['README.md','analysis/world_next.md','analysis/stack_release_v0285.md','analysis/stack_release_v0285_report.json','analysis/stack_release_v0285_worklog_prefix.json','analysis/dialogue_vblank_v0284_report.json','analysis/dialogue_vblank_v0285_report.json','analysis/sprite_mask_production_v0283_report.json','analysis/sprite_mask_production_v0284_report.json']]
 m=freeze(ROOT,ROOT/'analysis/stack-release-v0285',paths,dict(md_sha256=r['md_sha256'],full_game_validated=False,numbered_roms_preserved=285,protected_sha256=before),roots,cleanup=True)
 for name,digest in before.items():assert sha((ROOT/name).read_bytes())==digest
 # All removed captures remain readable through the archive fallback.
 from summarize_stack_release_v0285 import main as summarize
 original=(ROOT/'analysis/stack_release_v0285_report.json').read_bytes();summarize();assert (ROOT/'analysis/stack_release_v0285_report.json').read_bytes()==original
 print('All285 numbered ROMs preserved. Verified generated bytes removed:',sum(v['bytes'] for v in m['removed_verified_generated']))


if __name__=='__main__':main()
